window.GameModules.promptTemplates.inline["inference-update-emotion"] = "---\r\nname: emotion-update\r\ndescription: 根据现实推演正文提取玩家或角色的即时情绪变化更新\r\n---\r\n\r\n# Stage4 情绪更新\r\n\r\n触发角色或玩家即时情绪变化时，使用“情绪”结算类型输出中文 K:V 更新。\r\n\r\n- 绑定卡片：角色卡；玩家本人绑定玩家卡。\r\n- 结算对象类型：玩家或角色。\r\n- **field**：情绪指标名，只能使用固定 22 项：高兴、兴奋、悲伤、绝望、失落、委屈、恐惧、担忧、紧张、愤怒、烦躁、羞耻、愧疚、嫉妒、厌恶、惊讶、好奇、困惑、冷静、麻木、孤独、感动；只能写基线已有项。\r\n- **value**：本回合变化量，写 +N 或 -N。\r\n- **status**：变化后该情绪在当前数值下的具体表现；写角色此刻如何被这项情绪影响，禁止写“高兴40：”这类“指标名+数值+冒号”前缀，也不要在 reason 里重复程度解释。\r\n- **reason**：正文中的具体行为、对话或连续动作证据；只写证据本身，不要重复 field 名，不要写“因为情绪…”这类前缀；须与角色/玩家本质偏好五层相容，可点明与哪一层一致或形成何种张力。\r\n\r\n只写稳定可解释变化；普通氛围描写不写。\r\n";


