window.GameModules.promptTemplates.inline["inference-update-feeling"] = "---\r\nname: feeling-update\r\ndescription: 根据现实推演正文提取角色或玩家对玩家本人的感觉变化更新\r\n---\r\n\r\n# Stage4 感觉更新\r\n\r\n触发角色对玩家本人的感觉变化时，使用“感觉”结算类型输出中文 K:V 更新。\r\n\r\n- 绑定卡片：角色卡；玩家本人绑定玩家卡。\r\n- 结算对象类型：出场 NPC（不能是玩家本人）。\r\n- **field**：对玩家的感觉指标名，只能使用固定 25 项：了解、信任、警惕、好感、友情、亲情、爱情、想念、感恩、愧疚、同情、怜惜、讨厌、怨怼、敌意、反抗、服从、支配、占有、畏惧、尊敬、崇拜、依赖、期待、肉欲；只能写基线已有项。\r\n- **value**：本回合变化量，写 +N 或 -N。\r\n- **status**：变化后该感觉在当前数值下的具体表现；写 NPC 此刻对玩家的态度如何被这项感觉影响，禁止写“信任40：”这类“指标名+数值+冒号”前缀，也不要在 reason 里重复程度解释。\r\n- **reason**：正文中证明该 NPC 对玩家态度变化的具体证据；只写证据本身，不要重复 field 名，不要写“因为感觉…”这类前缀；须与 NPC 本质偏好五层相容，可点明与哪一层一致或形成何种张力。\r\n\r\n没有明确关系变化时不写。\r\n";


